CREATE OR REPLACE FUNCTION private.accept_practice_invitation(p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    invitation private.practice_invitations;
    member public.practice_memberships;
    actor uuid := auth.uid();
begin
    if actor is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text,0));
    select * into invitation from private.practice_invitations where token_digest=p_token_digest;
    if not found then return '{"status":"invalid-invitation"}'::jsonb; end if;
    perform 1 from public.practices where id=invitation.practice_id for update;
    invitation := private.invitation_for_actor(p_token_digest);
    if invitation.id is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    select * into member from public.practice_memberships where user_id=actor and state='active';
    if found then
        if member.practice_id <> invitation.practice_id then return '{"status":"other-practice"}'::jsonb; end if;
        return pg_catalog.jsonb_build_object('status','already-member','practiceId',member.practice_id,'role',member.role);
    end if;
    if invitation.state <> 'pending' then return '{"status":"invalid-invitation"}'::jsonb; end if;
    insert into public.practice_memberships (practice_id,user_id,role)
    values(invitation.practice_id,actor,invitation.role)
    on conflict(practice_id,user_id) do update set role=excluded.role,state='active',
        version=practice_memberships.version+1,updated_at=pg_catalog.clock_timestamp()
    returning * into member;
    update private.practice_invitations set state='accepted',accepted_user_id=actor,
        accepted_at=pg_catalog.clock_timestamp(),version=version+1,updated_at=pg_catalog.clock_timestamp()
    where id=invitation.id;
    return pg_catalog.jsonb_build_object('status','success','practiceId',member.practice_id,'role',member.role);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice(p_name text, p_timezone text)
 RETURNS practices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result public.practices;
    actor uuid := auth.uid();
begin
    if actor is null or not exists (select 1 from auth.users
                                   where id = actor and email_confirmed_at is not null) then
        raise exception 'forbidden' using errcode = '42501';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text, 0));
    select p.* into result from public.practices as p
    join public.practice_memberships as m on m.practice_id = p.id
    where m.user_id = actor and m.state = 'active';
    if found then return result; end if;
    insert into public.practices (name, timezone) values (p_name, p_timezone)
    returning * into result;
    insert into public.practice_memberships (practice_id, user_id, role)
    values (result.id, actor, 'administrator');
    insert into private.practice_reminder_settings (practice_id) values (result.id);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_clinician(p_practice_id uuid, p_request_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    payload jsonb;
    result jsonb;
    clinician public.clinicians;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_name);
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    payload := pg_catalog.jsonb_build_object('name', normalized);
    result := private.register_replay(p_practice_id, p_request_id, 'clinician-created', payload);
    if result is not null then return result; end if;
    insert into public.clinicians (practice_id, name) values (p_practice_id, normalized)
    returning * into clinician;
    result := pg_catalog.jsonb_build_object('status', 'success', 'clinician',
        pg_catalog.jsonb_build_object('id', clinician.id, 'name', clinician.name,
            'version', clinician.version));
    return private.finish_register_create(p_practice_id, p_request_id, 'clinician-created', payload,
        clinician.id, null, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
    result jsonb;
    credential public.credentials;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_title);
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered);
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', payload);
    if result is not null then return result; end if;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (
        select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )
    ) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id)
    values (p_practice_id, normalized, p_type, p_owner_kind, p_owner_clinician_id)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created', payload,
        null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential_with_details(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[], p_issuer text, p_jurisdiction text, p_end_date text, p_action_deadline text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    issuer text;
    jurisdiction text;
    entered_end_date date;
    entered_action_deadline date;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
    result jsonb;
    credential public.credentials;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_title);
    issuer := nullif(private.register_name(p_issuer), '');
    jurisdiction := nullif(private.register_name(p_jurisdiction), '');
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if issuer is not null and char_length(issuer) > 120 then
        return '{"status":"invalid","errors":{"issuer":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    if jurisdiction is not null and char_length(jurisdiction) > 120 then
        return '{"status":"invalid","errors":{"jurisdiction":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    begin
        entered_end_date := private.credential_date(p_end_date);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"endDate":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    begin
        entered_action_deadline := private.credential_date(p_action_deadline);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"actionDeadline":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    if entered_end_date is not null and entered_action_deadline is not null and entered_action_deadline >= entered_end_date then
        return '{"status":"invalid","errors":{"actionDeadline":"The action deadline must be earlier than the end date."}}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered, 'contract_version', 2, 'issuer', issuer,
        'jurisdiction', jurisdiction, 'end_date', pg_catalog.to_char(entered_end_date, 'YYYY-MM-DD'),
        'action_deadline', pg_catalog.to_char(entered_action_deadline, 'YYYY-MM-DD'));
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', payload);
    if result is not null then return result; end if;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (
        select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )
    ) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id, issuer, jurisdiction)
    values (p_practice_id, normalized, p_type, p_owner_kind, p_owner_clinician_id, issuer, jurisdiction)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    update public.credential_cycles cy set end_date = entered_end_date,
        action_deadline = entered_action_deadline,
        updated_at = pg_catalog.clock_timestamp()
    where cy.practice_id = p_practice_id and cy.credential_id = credential.id and cy.cycle_number = 1;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_details_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created', payload,
        null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_invitation(p_practice_id uuid, p_email text, p_role text, p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    canonical text;
    issued timestamptz;
    result private.practice_invitations;
begin
    perform private.require_administrator(p_practice_id);
    canonical := private.canonical_invitation_email(p_email);
    if p_role is null or p_role not in ('administrator','manager','viewer')
       or p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$' then
        raise exception 'Invalid invitation' using errcode='23514';
    end if;
    if exists(select 1 from private.practice_invitations
              where practice_id=p_practice_id and email=canonical and state='pending') then
        return '{"status":"invite-exists"}'::jsonb;
    end if;
    issued := pg_catalog.clock_timestamp();
    insert into private.practice_invitations
        (practice_id,email,role,token_digest,creator_user_id,issued_at,expires_at)
    values(p_practice_id,canonical,p_role,p_token_digest,auth.uid(),issued,issued+interval '168 hours')
    returning * into result;
    return pg_catalog.jsonb_build_object('status','success','invitation',private.invitation_projection(result));
end;
$function$

CREATE OR REPLACE FUNCTION private.credential_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
    if p_value is null or p_value = '' then return null; end if;
    if char_length(p_value) <> 10 or p_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or substring(p_value from 1 for 4)::integer = 0 then
        raise exception 'invalid credential date' using errcode = '22008';
    end if;
    return pg_catalog.make_date(substring(p_value from 1 for 4)::integer,
        substring(p_value from 6 for 2)::integer, substring(p_value from 9 for 2)::integer);
end;
$function$

CREATE OR REPLACE FUNCTION private.credential_details_projection(p_record credentials)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
    cycle public.credential_cycles;
begin
    select * into cycle from public.credential_cycles
    where practice_id = p_record.practice_id and credential_id = p_record.id and cycle_number = 1;
    if not found then raise exception 'missing credential cycle'; end if;
    return private.credential_projection(p_record) || pg_catalog.jsonb_build_object(
        'issuer', p_record.issuer, 'jurisdiction', p_record.jurisdiction,
        'current_cycle', pg_catalog.jsonb_build_object('id', cycle.id,
            'cycle_number', cycle.cycle_number, 'date_revision', cycle.date_revision,
            'end_date', pg_catalog.to_char(cycle.end_date, 'YYYY-MM-DD'),
            'action_deadline', pg_catalog.to_char(cycle.action_deadline, 'YYYY-MM-DD')));
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_administrator()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    target uuid;
begin
    if tg_table_name = 'practices' then
        target := new.id;
    elsif tg_op = 'DELETE' then
        target := old.practice_id;
    else
        target := new.practice_id;
    end if;
    perform 1 from public.practices where id = target for update;
    if found and not exists (select 1 from public.practice_memberships
                             where practice_id = target and state = 'active'
                               and role = 'administrator') then
        raise exception 'Practice requires an active administrator' using errcode = '23514';
    end if;
    if tg_table_name = 'practice_memberships' then
        if tg_op = 'UPDATE' then
            if old.practice_id <> new.practice_id then
                raise exception 'Membership practice is immutable' using errcode = '23514';
            end if;
        end if;
    end if;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.get_practice_reminder_recipient(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    can_edit boolean;
    settings private.practice_reminder_settings;
    selected jsonb;
    readiness text;
    result jsonb;
begin
    can_edit := private.require_recipient_member(p_practice_id, false);
    select * into settings from private.practice_reminder_settings where practice_id = p_practice_id;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    select pg_catalog.jsonb_build_object('id', m.id, 'email', u.email, 'role', m.role, 'state', m.state)
    into selected from public.practice_memberships m join auth.users u on u.id = m.user_id
    where m.practice_id = p_practice_id and m.id = settings.membership_id;
    readiness := case when settings.membership_id is null then 'no-recipient'
        when selected->>'state' = 'active' and selected->>'role' in ('administrator', 'manager')
            then 'sms-setup-pending' else 'member-unavailable' end;
    result := pg_catalog.jsonb_build_object('version', settings.version, 'selected', selected,
        'readiness', readiness, 'ready', false, 'canEdit', can_edit);
    if can_edit then
        result := result || pg_catalog.jsonb_build_object('candidates', coalesce((
            select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'id', m.id, 'email', u.email, 'role', m.role, 'state', m.state) order by m.created_at, m.id)
            from public.practice_memberships m join auth.users u on u.id = m.user_id
            where m.practice_id = p_practice_id and m.state = 'active'
                and m.role in ('administrator', 'manager')
        ), '[]'::jsonb));
    end if;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.initialize_credential_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    insert into public.credential_cycles (practice_id, credential_id) values (new.practice_id, new.id);
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.invalidate_reminder_recipient(p_practice_id uuid, p_membership_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    settings private.practice_reminder_settings;
begin
    select * into settings from private.practice_reminder_settings
    where practice_id = p_practice_id for update;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    if settings.membership_id = p_membership_id then
        perform private.change_reminder_recipient(p_practice_id, null, p_reason);
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.invitation_for_actor(p_token_digest text)
 RETURNS private.practice_invitations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result private.practice_invitations;
    actor_email text;
    latest_revocation timestamptz;
begin
    if p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$' then return null; end if;
    select email into actor_email from auth.users
    where id=auth.uid() and email_confirmed_at is not null;
    if actor_email is null then return null; end if;
    select * into result from private.practice_invitations where token_digest=p_token_digest;
    if not found then return null; end if;
    if result.email <> private.canonical_invitation_email(actor_email)
       or result.state='canceled' or pg_catalog.clock_timestamp() >= result.expires_at then return null; end if;
    select revoked_at into latest_revocation from public.practice_memberships
    where practice_id=result.practice_id and user_id=auth.uid();
    if result.state='pending' and latest_revocation is not null
       and result.issued_at <= latest_revocation then return null; end if;
    if result.state='accepted' and (result.accepted_user_id <> auth.uid()
       or not exists(select 1 from public.practice_memberships where practice_id=result.practice_id
                     and user_id=auth.uid() and state='active')) then return null; end if;
    return result;
exception when check_violation then return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.list_practice_register(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform private.require_register_member(p_practice_id, false);
    return pg_catalog.jsonb_build_object(
        'clinicians', coalesce((
            select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'id', id, 'name', name, 'version', version) order by created_at, id)
            from public.clinicians where practice_id = p_practice_id
        ), '[]'::jsonb),
        'credentials', coalesce((
            select pg_catalog.jsonb_agg(private.credential_details_projection(c) order by c.created_at, c.id)
            from public.credentials c where c.practice_id = p_practice_id
        ), '[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION private.mutate_invitation(p_invitation_id uuid, p_expected_version integer, p_token_digest text, p_reissue boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result private.practice_invitations;
    issued timestamptz;
begin
    select * into result from private.practice_invitations where id=p_invitation_id;
    perform private.require_administrator(result.practice_id);
    select * into result from private.practice_invitations where id=p_invitation_id for update;
    if p_expected_version is null or p_expected_version < 1 then
        raise exception 'Invalid version' using errcode='23514';
    end if;
    if not p_reissue and result.state='canceled' then
        return pg_catalog.jsonb_build_object('status','success','invitation',private.invitation_projection(result));
    end if;
    if result.version <> p_expected_version or result.state <> 'pending' then
        return '{"status":"conflict"}'::jsonb;
    end if;
    issued := pg_catalog.clock_timestamp();
    if p_reissue then
        if p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$'
           or p_token_digest=result.token_digest then
            raise exception 'Invalid new digest' using errcode='23514';
        end if;
        update private.practice_invitations set token_digest=p_token_digest,
            issued_at=issued,expires_at=issued+interval '168 hours',version=version+1,updated_at=issued
        where id=p_invitation_id returning * into result;
    else
        update private.practice_invitations set state='canceled',version=version+1,updated_at=issued
        where id=p_invitation_id returning * into result;
    end if;
    return pg_catalog.jsonb_build_object('status','success','invitation',private.invitation_projection(result));
end;
$function$

CREATE OR REPLACE FUNCTION private.mutate_member(p_membership_id uuid, p_expected_version integer, p_role text, p_revoke boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    member public.practice_memberships;
begin
    select * into member from public.practice_memberships where id=p_membership_id;
    perform private.require_administrator(member.practice_id);
    select * into member from public.practice_memberships where id=p_membership_id for update;
    if p_expected_version is null or p_expected_version < 1 or
       (not p_revoke and (p_role is null or p_role not in ('administrator','manager','viewer'))) then
        raise exception 'Invalid member input' using errcode='23514';
    end if;
    if p_revoke and member.state='revoked' then return '{"status":"success"}'::jsonb; end if;
    if member.version <> p_expected_version or member.state <> 'active' then return '{"status":"conflict"}'::jsonb; end if;
    if member.role='administrator' and (p_revoke or p_role <> 'administrator')
       and (select count(*) from public.practice_memberships where practice_id=member.practice_id
            and role='administrator' and state='active') <= 1 then return '{"status":"last-administrator"}'::jsonb; end if;
    if not p_revoke and member.role=p_role then return '{"status":"success"}'::jsonb; end if;
    if p_revoke then
        update public.practice_memberships set state='revoked',revoked_at=pg_catalog.clock_timestamp(),
            version=version+1,updated_at=pg_catalog.clock_timestamp() where id=p_membership_id;
    else
        update public.practice_memberships set role=p_role,version=version+1,
            updated_at=pg_catalog.clock_timestamp() where id=p_membership_id;
    end if;
    if p_revoke or p_role = 'viewer' then
        perform private.invalidate_reminder_recipient(member.practice_id, p_membership_id,
            case when p_revoke then 'revoked' else 'role-viewer' end);
    end if;
    return '{"status":"success"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.preview_practice_invitation(p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    invitation private.practice_invitations;
    invited_role text;
begin
    invitation := private.invitation_for_actor(p_token_digest);
    if invitation.id is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    invited_role := invitation.role;
    if invitation.state='accepted' then
        select role into invited_role from public.practice_memberships
        where practice_id=invitation.practice_id and user_id=auth.uid() and state='active';
    end if;
    return pg_catalog.jsonb_build_object('status','success','name',
        (select name from public.practices where id=invitation.practice_id),
        'role',invited_role,'expires_at',invitation.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION private.register_replay(p_practice_id uuid, p_request_id uuid, p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    receipt private.register_create_requests;
begin
    select * into receipt from private.register_create_requests
    where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id;
    if not found then return null; end if;
    if receipt.operation <> p_operation or receipt.payload <> p_payload then
        return '{"status":"request-conflict"}'::jsonb;
    end if;
    return receipt.result;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_recipient_member(p_practice_id uuid, p_edit boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    actor_role text;
begin
    perform 1 from public.practices where id = p_practice_id for update;
    select role into actor_role from public.practice_memberships
    where practice_id = p_practice_id and user_id = auth.uid() and state = 'active';
    if actor_role is null or (p_edit and actor_role not in ('administrator', 'manager')) then
        raise exception 'forbidden' using errcode = '42501';
    end if;
    return actor_role in ('administrator', 'manager');
end;
$function$

CREATE OR REPLACE FUNCTION private.require_register_member(p_practice_id uuid, p_edit boolean)
 RETURNS void
